# ./routes.py
from flask import render_template, request, redirect, url_for, flash, jsonify, session
from flask_login import login_user, logout_user, login_required, current_user
from urllib.parse import parse_qs, urlparse
from datetime import datetime, timedelta
import logging

from app import app, db
from models import User, Payment, PaymentLink, Account, Transaction
from erste_api import ErsteAPIClient
from payment_processor import PaymentProcessor

logger = logging.getLogger(__name__)

erste_client = ErsteAPIClient()
payment_processor = PaymentProcessor()

@app.route('/')
def index():
    """Home page"""
    return render_template('index.html')

@app.route('/dashboard')
@login_required
def dashboard():
    """User dashboard"""
    payments = Payment.query.filter_by(user_id=current_user.id).order_by(Payment.created_at.desc()).limit(10).all()
    accounts = Account.query.filter_by(user_id=current_user.id).all()
    payment_links = PaymentLink.query.filter_by(user_id=current_user.id, is_active=True).all()

    return render_template('dashboard.html', 
                         payments=payments, 
                         accounts=accounts, 
                         payment_links=payment_links)

@app.route('/auth/login', methods=['GET', 'POST'])
def login():
    """User login"""
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')

        user = User.query.filter_by(username=username).first()

        if user and user.check_password(password):
            login_user(user)
            next_page = request.args.get('next')
            return redirect(next_page) if next_page else redirect(url_for('dashboard'))
        else:
            flash('Érvénytelen felhasználónév vagy jelszó', 'error')

    return render_template('auth.html', mode='login')

@app.route('/auth/register', methods=['GET', 'POST'])
def register():
    """User registration"""
    if request.method == 'POST':
        username = request.form.get('username')
        email = request.form.get('email')
        password = request.form.get('password')

        if User.query.filter_by(username=username).first():
            flash('A felhasználónév már foglalt', 'error')
            return render_template('auth.html', mode='register')

        if User.query.filter_by(email=email).first():
            flash('Ez az email cím már regisztrálva van', 'error')
            return render_template('auth.html', mode='register')

        user = User(username=username, email=email)
        user.set_password(password)

        db.session.add(user)
        db.session.commit()

        flash('Sikeres regisztráció! Kérjük, jelentkezzen be.', 'success')
        return redirect(url_for('login'))

    return render_template('auth.html', mode='register')

@app.route('/auth/logout')
@login_required
def logout():
    """User logout"""
    logout_user()
    return redirect(url_for('index'))

@app.route('/auth/erste')
@login_required
def erste_auth():
    """Initiate Erste Bank authentication"""
    try:
        consent_data = erste_client.create_consent()
        consent_id = consent_data.get('consentId')

        if not consent_id:
            flash('Hiba a consent létrehozásakor', 'error')
            return redirect(url_for('dashboard'))

        current_user.consent_id = consent_id
        db.session.commit()

        auth_url = erste_client.get_authorization_url(consent_id)

        return redirect(auth_url)

    except Exception as e:
        logger.error(f"Error initiating Erste auth: {e}")
        flash('Hiba az Erste Bank hitelesítés során', 'error')
        return redirect(url_for('dashboard'))

@app.route('/auth/callback')
@login_required
def auth_callback():
    """Handle Erste Bank OAuth callback"""
    try:
        code = request.args.get('code')
        state = request.args.get('state')
        error = request.args.get('error')

        if error:
            flash(f'Hitelesítési hiba: {error}', 'error')
            return redirect(url_for('dashboard'))

        if not code or not state:
            flash('Hiányzó hitelesítési paraméterek', 'error')
            return redirect(url_for('dashboard'))

        token_data = erste_client.exchange_code_for_token(code, state)

        current_user.access_token = token_data.get('access_token')
        current_user.refresh_token = token_data.get('refresh_token')
        current_user.token_expires_at = datetime.utcnow() + timedelta(seconds=token_data.get('expires_in', 3600))
        db.session.commit()

        accounts_data = erste_client.get_accounts(current_user.access_token)

        for account_data in accounts_data.get('accounts', []):
            account = Account.query.filter_by(
                user_id=current_user.id,
                account_id=account_data.get('resourceId')
            ).first()

            if not account:
                account = Account(
                    user_id=current_user.id,
                    account_id=account_data.get('resourceId'),
                    iban=account_data.get('iban'),
                    name=account_data.get('name'),
                    currency=account_data.get('currency', 'HUF'),
                    account_type=account_data.get('cashAccountType')
                )
                db.session.add(account)

        db.session.commit()

        flash('Sikeres Erste Bank hitelesítés!', 'success')
        return redirect(url_for('dashboard'))

    except Exception as e:
        logger.error(f"Error in auth callback: {e}")
        flash('Hiba a hitelesítés során', 'error')
        return redirect(url_for('dashboard'))

@app.route('/payment/create', methods=['GET', 'POST'])
@login_required
def create_payment():
    """Create a new payment"""
    if request.method == 'POST':
        try:
            payment_method = request.form.get('payment_method')
            amount = float(request.form.get('amount'))
            currency = request.form.get('currency', 'HUF')
            recipient_name = request.form.get('recipient_name')
            recipient_iban = request.form.get('recipient_iban')
            debtor_iban = request.form.get('debtor_iban')
            description = request.form.get('description', '')

            payment_data = {
                'amount': amount,
                'currency': currency,
                'recipient_name': recipient_name,
                'recipient_iban': recipient_iban,
                'debtor_iban': debtor_iban,
                'description': description
            }

            if payment_method == 'erste':
                result = payment_processor.process_erste_payment(current_user.id, payment_data)
            elif payment_method == 'apple_pay':
                payment_data['apple_pay_token'] = request.form.get('apple_pay_token')
                result = payment_processor.process_apple_pay(current_user.id, payment_data)
            elif payment_method == 'google_pay':
                payment_data['google_pay_token'] = request.form.get('google_pay_token')
                result = payment_processor.process_google_pay(current_user.id, payment_data)
            elif payment_method == 'coinbase':
                result = payment_processor.process_coinbase_payment(current_user.id, payment_data)
                if result['success']:
                    return redirect(result['hosted_url'])
            else:
                flash('Érvénytelen fizetési mód', 'error')
                return redirect(url_for('create_payment'))

            if result['success']:
                flash('Fizetés sikeresen elindítva!', 'success')
                return redirect(url_for('dashboard'))
            else:
                flash('Hiba a fizetés során', 'error')

        except Exception as e:
            logger.error(f"Error creating payment: {e}")
            flash('Hiba a fizetés létrehozásakor', 'error')

    accounts = Account.query.filter_by(user_id=current_user.id).all()
    return render_template('create_payment.html', accounts=accounts)

@app.route('/payment/link/create', methods=['GET', 'POST'])
@login_required
def create_payment_link():
    """Create a new payment link"""
    if request.method == 'POST':
        try:
            amount = float(request.form.get('amount'))
            currency = request.form.get('currency', 'HUF')
            description = request.form.get('description', '')
            expires_hours = int(request.form.get('expires_hours', 24))
            max_uses = int(request.form.get('max_uses', 1))

            payment_link = PaymentLink(
                user_id=current_user.id,
                amount=amount,
                currency=currency,
                description=description,
                expires_at=datetime.utcnow() + timedelta(hours=expires_hours),
                max_uses=max_uses
            )

            db.session.add(payment_link)
            db.session.commit()

            flash('Fizetési link sikeresen létrehozva!', 'success')
            return redirect(url_for('dashboard'))

        except Exception as e:
            logger.error(f"Error creating payment link: {e}")
            flash('Hiba a fizetési link létrehozásakor', 'error')

    return render_template('payment_link.html')

@app.route('/pay/<link_id>', methods=['GET', 'POST'])
def pay_via_link(link_id):
    """Pay via payment link"""
    payment_link = PaymentLink.query.filter_by(link_id=link_id, is_active=True).first()

    if not payment_link:
        flash('Érvénytelen vagy lejárt fizetési link', 'error')
        return redirect(url_for('index'))

    if payment_link.expires_at and payment_link.expires_at < datetime.utcnow():
        flash('A fizetési link lejárt', 'error')
        return redirect(url_for('index'))

    if payment_link.current_uses >= payment_link.max_uses:
        flash('A fizetési link elérte a maximális használatok számát', 'error')
        return redirect(url_for('index'))

    if request.method == 'POST':
        try:
            payment_method = request.json.get('payment_method')
            payer_name = request.json.get('payer_name')

            if payment_method == 'coinbase':
                payment_data = {
                    'amount': float(payment_link.amount),
                    'currency': payment_link.currency,
                    'description': f"{payment_link.description} - {payer_name}",
                    'recipient_name': payer_name
                }

                result = payment_processor.process_coinbase_payment(payment_link.user_id, payment_data)

                payment_link.current_uses += 1
                if payment_link.current_uses >= payment_link.max_uses:
                    payment_link.is_active = False

                db.session.commit()

                return jsonify({
                    'success': True,
                    'redirect_url': result['hosted_url']
                })

            elif payment_method == 'erste_bank':
                payment_data = {
                    'amount': float(payment_link.amount),
                    'currency': payment_link.currency,
                    'recipient_name': payer_name,
                    'description': payment_link.description,
                    'debtor_iban': '',
                    'recipient_iban': '',
                }

                payment = Payment(
                    user_id=payment_link.user_id,
                    amount=payment_link.amount,
                    currency=payment_link.currency,
                    payment_method='erste',
                    recipient_name=payer_name,
                    description=payment_link.description,
                    status='pending'
                )

                db.session.add(payment)

                payment_link.current_uses += 1
                if payment_link.current_uses >= payment_link.max_uses:
                    payment_link.is_active = False

                db.session.commit()

                return jsonify({
                    'success': True,
                    'redirect_url': url_for('payment_success', payment_id=payment.payment_id)
                })

        except Exception as e:
            logger.error(f"Error processing payment link: {e}")
            return jsonify({'success': False, 'error': str(e)})

    return render_template('pay_link.html', payment_link=payment_link)

