@app.route('/api/accounts/refresh')
@login_required
def refresh_accounts():
    """Refresh user accounts from Erste API"""
    try:
        if not current_user.access_token:
            return jsonify({'success': False, 'error': 'Not authenticated with Erste Bank'})

        accounts_data = erste_client.get_accounts(current_user.access_token)

        for account_data in accounts_data.get('accounts', []):
            account = Account.query.filter_by(
                user_id=current_user.id,
                account_id=account_data.get('resourceId')
            ).first()

            if account:
                account.name = account_data.get('name')
                account.currency = account_data.get('currency', 'HUF')
                account.last_updated = datetime.utcnow()
            else:
                account = Account(
                    user_id=current_user.id,
                    account_id=account_data.get('resourceId'),
                    iban=account_data.get('iban'),
                    name=account_data.get('name'),
                    currency=account_data.get('currency', 'HUF'),
                    account_type=account_data.get('cashAccountType')
                )
                db.session.add(account)

        db.session.commit()

        return jsonify({'success': True, 'message': 'Accounts refreshed successfully'})

    except Exception as e:
        logger.error(f"Error refreshing accounts: {e}")
        return jsonify({'success': False, 'error': str(e)})

@app.route('/api/payout/instant', methods=['POST'])
@login_required
def instant_payout():
    """Process instant payout"""
    try:
        data = request.get_json()
        account_id = data.get('account_id')
