@app.route('/api/apple-pay/validate-merchant', methods=['POST'])
@login_required
def validate_apple_pay_merchant():
    """Validate merchant for Apple Pay"""
    try:
        data = request.get_json()
        validation_url = data.get('validationURL')

        return jsonify({
            'success': True,
            'merchantSession': {
                'merchantId': 'merchant.fizetesiprocesszor.hu',
