@app.route('/api/apple-pay/process-payment', methods=['POST'])
@login_required
def process_apple_pay_payment():
    """Process Apple Pay payment"""
    try:
        data = request.get_json()
        payment_token = data.get('paymentToken')
        payment_data = data.get('paymentData')

        result = payment_processor.process_apple_pay(current_user.id, {
            'amount': payment_data.get('amount'),
            'currency': payment_data.get('currency', 'HUF'),
            'apple_pay_token': payment_token,
            'description': payment_data.get('label', 'Apple Pay payment')
        })

        return jsonify(result)

    except Exception as e:
        logger.error(f"Error processing Apple Pay payment: {e}")
        return jsonify({'success': False, 'error': str(e)})

@app.route('/api/google-pay/process-payment', methods=['POST'])
@login_required
def process_google_pay_payment():
    """Process Google Pay payment"""
    try:
        data = request.get_json()
        payment_token = data.get('paymentToken')
        payment_data = data.get('paymentData')

        result = payment_processor.process_google_pay(current_user.id, {
            'amount': payment_data.get('amount'),
            'currency': payment_data.get('currency', 'HUF'),
            'google_pay_token': payment_token,
