        })

        return jsonify(result)

    except Exception as e:
        logger.error(f"Error processing Google Pay payment: {e}")
        return jsonify({'success': False, 'error': str(e)})

@app.route('/webhook/coinbase', methods=['POST'])
def coinbase_webhook():
    """Handle Coinbase Commerce webhook events"""
    try:
        payload = request.data
        signature = request.headers.get('X-CC-Webhook-Signature', '')

        if not payment_processor.coinbase_client.verify_webhook_signature(payload, signature):
            logger.warning("Invalid Coinbase webhook signature")
            return jsonify({'error': 'Invalid signature'}), 401

        event_data = request.get_json()
        result = payment_processor.handle_coinbase_webhook(event_data)

        if result['success']:
            return jsonify({'success': True}), 200
        else:
            return jsonify({'error': result.get('error')}), 400

    except Exception as e:
        logger.error(f"Error handling Coinbase webhook: {e}")
        return jsonify({'error': str(e)}), 500

@app.errorhandler(404)
