// ./static/js/apple_pay.js
class ApplePayManager {
    constructor() {
        this.merchantIdentifier = 'merchant.fizetesiprocesszor.hu';
        this.countryCode = 'HU';
        this.currencyCode = 'HUF';
        this.supportedNetworks = ['visa', 'masterCard', 'amex'];
        this.merchantCapabilities = ['supports3DS'];
    }

    isAvailable() {
        if (window.ApplePaySession) {
            return ApplePaySession.canMakePayments();
        }
        return false;
    }

    async startPayment(amount, label) {
        if (!this.isAvailable()) {
            throw new Error('Apple Pay is not available on this device');
        }

        const request = {
            countryCode: this.countryCode,
            currencyCode: this.currencyCode,
            supportedNetworks: this.supportedNetworks,
            merchantCapabilities: this.merchantCapabilities,
            total: {
                label: label || 'Fizetés',
                amount: amount.toString()
            }
        };

        const session = new ApplePaySession(3, request);

        session.onvalidatemerchant = async (event) => {
            try {
                const merchantSession = await this.validateMerchant(event.validationURL);
                session.completeMerchantValidation(merchantSession);
            } catch (error) {
                console.error('Merchant validation failed:', error);
                session.abort();
            }
        };

        session.onpaymentauthorized = async (event) => {
            try {
                const result = await this.processPayment(event.payment);

                if (result.success) {
                    session.completePayment(ApplePaySession.STATUS_SUCCESS);
                    this.onPaymentSuccess(result);
                } else {
                    session.completePayment(ApplePaySession.STATUS_FAILURE);
                    this.onPaymentFailure(result.error);
                }
            } catch (error) {
                console.error('Payment processing failed:', error);
                session.completePayment(ApplePaySession.STATUS_FAILURE);
                this.onPaymentFailure(error.message);
            }
        };

        session.oncancel = (event) => {
            console.log('Apple Pay session cancelled');
            this.onPaymentCancel();
        };

        session.begin();
    }

    async validateMerchant(validationURL) {
        const response = await fetch('/api/apple-pay/validate-merchant', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                validationURL: validationURL
            })
        });

        if (!response.ok) {
            throw new Error('Merchant validation failed');
        }

        const data = await response.json();
        return data.merchantSession;
    }

    async processPayment(payment) {
        const response = await fetch('/api/apple-pay/process-payment', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                paymentToken: payment.token,
                paymentData: {
                    amount: payment.token.transactionAmount,
                    currency: this.currencyCode,
                    label: payment.token.transactionIdentifier
                }
            })
        });

        if (!response.ok) {
            throw new Error('Payment processing failed');
        }

        return await response.json();
    }

    onPaymentSuccess(result) {
        console.log('Payment successful:', result);
        window.location.href = '/payment/success?payment_id=' + result.payment_id;
    }

    onPaymentFailure(error) {
        console.error('Payment failed:', error);
        window.location.href = '/payment/failed?error=' + encodeURIComponent(error);
    }

    onPaymentCancel() {
        console.log('Payment cancelled by user');
    }
}

window.ApplePayManager = ApplePayManager;


