class GooglePayManager {
    constructor() {
        this.baseRequest = {
            apiVersion: 2,
            apiVersionMinor: 0
        };

        this.allowedCardNetworks = ['MASTERCARD', 'VISA', 'AMEX'];
        this.allowedCardAuthMethods = ['PAN_ONLY', 'CRYPTOGRAM_3DS'];

        this.tokenizationSpecification = {
            type: 'PAYMENT_GATEWAY',
            parameters: {
                'gateway': 'erste',
                'gatewayMerchantId': 'your-merchant-id'
            }
        };

        this.baseCardPaymentMethod = {
            type: 'CARD',
            parameters: {
                allowedAuthMethods: this.allowedCardAuthMethods,
                allowedCardNetworks: this.allowedCardNetworks
            }
        };

        this.cardPaymentMethod = Object.assign(
            {},
            this.baseCardPaymentMethod,
            {
                tokenizationSpecification: this.tokenizationSpecification
            }
        );

        this.paymentsClient = null;
    }

    getGooglePaymentsClient() {
        if (this.paymentsClient === null) {
            this.paymentsClient = new google.payments.api.PaymentsClient({
                environment: 'TEST' // Change to 'PRODUCTION' for production
            });
        }
        return this.paymentsClient;
    }

    async isReadyToPay() {
        const isReadyToPayRequest = Object.assign({}, this.baseRequest);
        isReadyToPayRequest.allowedPaymentMethods = [this.baseCardPaymentMethod];

        const client = this.getGooglePaymentsClient();
        const response = await client.isReadyToPay(isReadyToPayRequest);
        return response.result;
    }

    createButton(containerId, amount, label) {
        const client = this.getGooglePaymentsClient();
        const button = client.createButton({
            onClick: () => this.onGooglePaymentButtonClicked(amount, label)
        });
        document.getElementById(containerId).appendChild(button);
    }

    getGooglePaymentDataRequest(amount, label) {
        const paymentDataRequest = Object.assign({}, this.baseRequest);
        paymentDataRequest.allowedPaymentMethods = [this.cardPaymentMethod];
        paymentDataRequest.transactionInfo = this.getGoogleTransactionInfo(amount, label);
        paymentDataRequest.merchantInfo = {
            merchantName: 'Fizetési Processzor',
            merchantId: 'your-google-merchant-id'
        };

        return paymentDataRequest;
    }

    getGoogleTransactionInfo(amount, label) {
        return {
            countryCode: 'HU',
            currencyCode: 'HUF',
            totalPriceStatus: 'FINAL',
            totalPrice: amount.toString(),
            totalPriceLabel: label || 'Fizetés'
        };
    }

    async onGooglePaymentButtonClicked(amount, label) {
        const paymentDataRequest = this.getGooglePaymentDataRequest(amount, label);

        const client = this.getGooglePaymentsClient();
        try {
            const paymentData = await client.loadPaymentData(paymentDataRequest);
            await this.processPayment(paymentData, amount, label);
        } catch (error) {
            console.error('Google Pay error:', error);
            this.onPaymentFailure(error.message);
        }
    }

    async processPayment(paymentData, amount, label) {
        const paymentToken = paymentData.paymentMethodData.tokenizationData.token;

        const response = await fetch('/api/google-pay/process-payment', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                paymentToken: paymentToken,
                paymentData: {
                    amount: amount,
                    currency: 'HUF',
                    label: label
                }
            })
        });

        if (!response.ok) {
            throw new Error('Payment processing failed');
        }

        const result = await response.json();

        if (result.success) {
            this.onPaymentSuccess(result);
        } else {
            this.onPaymentFailure(result.error);
        }
    }

    onPaymentSuccess(result) {
        console.log('Payment successful:', result);
        window.location.href = '/payment/success?payment_id=' + result.payment_id;
    }

    onPaymentFailure(error) {
        console.error('Payment failed:', error);
        window.location.href = '/payment/failed?error=' + encodeURIComponent(error);
    }
}

