// ./static/js/main.js
document.addEventListener('DOMContentLoaded', function() {
    initializePaymentMethods();
    initializePaymentLinks();
    initializeTransactionRefresh();
    initializeModals();
    initializeCopyButtons();
});

function initializePaymentMethods() {
    const applePayButtons = document.querySelectorAll('.apple-pay-button');
    const googlePayButtons = document.querySelectorAll('.google-pay-button');

    if (applePayButtons.length > 0) {
        const applePayManager = new ApplePayManager();

        applePayButtons.forEach(button => {
            if (!applePayManager.isAvailable()) {
                button.style.display = 'none';
                return;
            }

            button.addEventListener('click', function() {
                const amount = this.getAttribute('data-amount');
                const label = this.getAttribute('data-label') || 'Fizetés';
                applePayManager.startPayment(parseFloat(amount), label);
            });
        });
    }

    if (googlePayButtons.length > 0 && typeof google !== 'undefined') {
        const googlePayManager = new GooglePayManager();

        googlePayManager.isReadyToPay().then(function(ready) {
            if (ready) {
                googlePayButtons.forEach(button => {
                    button.style.display = 'block';

                    button.addEventListener('click', function() {
                        const amount = this.getAttribute('data-amount');
                        const label = this.getAttribute('data-label') || 'Fizetés';
                        googlePayManager.onGooglePaymentButtonClicked(parseFloat(amount), label);
                    });
                });
            } else {
                googlePayButtons.forEach(button => {
                    button.style.display = 'none';
                });
            }
        });
    }
}

function initializePaymentLinks() {
    const paymentForms = document.querySelectorAll('.payment-link-form');

    paymentForms.forEach(form => {
        form.addEventListener('submit', async function(e) {
            e.preventDefault();

            const formData = new FormData(form);
            const paymentMethod = formData.get('payment_method');
            const payerName = formData.get('payer_name');

            try {
                const response = await fetch(form.action, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        payment_method: paymentMethod,
                        payer_name: payerName
                    })
                });

                const result = await response.json();

                if (result.success && result.redirect_url) {
                    window.location.href = result.redirect_url;
                } else {
                    showError('Hiba a fizetés során: ' + (result.error || 'Ismeretlen hiba'));
                }
            } catch (error) {
                console.error('Payment error:', error);
                showError('Hiba a fizetés során');
            }
        });
    });
}

function initializeTransactionRefresh() {
    const refreshButton = document.getElementById('refresh-accounts');

    if (refreshButton) {
        refreshButton.addEventListener('click', async function() {
            this.disabled = true;
            this.innerHTML = '<span class="loading"></span> Frissítés...';

            try {
                const response = await fetch('/api/accounts/refresh');
                const result = await response.json();

                if (result.success) {
                    showSuccess('Számlák sikeresen frissítve');
                    setTimeout(() => {
                        location.reload();
                    }, 1000);
                } else {
                    showError(result.error || 'Hiba a frissítés során');
                }
            } catch (error) {
                console.error('Refresh error:', error);
                showError('Hiba a frissítés során');
            } finally {
                this.disabled = false;
                this.innerHTML = 'Frissítés';
            }
        });
    }
}

function initializeModals() {
    const modalTriggers = document.querySelectorAll('[data-modal]');
    const modalCloses = document.querySelectorAll('.modal-close');

    modalTriggers.forEach(trigger => {
        trigger.addEventListener('click', function() {
            const modalId = this.getAttribute('data-modal');
            const modal = document.getElementById(modalId);
            if (modal) {
                modal.classList.add('active');
            }
        });
    });

    modalCloses.forEach(close => {
        close.addEventListener('click', function() {
            const modal = this.closest('.modal');
            if (modal) {
                modal.classList.remove('active');
            }
        });
    });

    document.querySelectorAll('.modal').forEach(modal => {
        modal.addEventListener('click', function(e) {
            if (e.target === this) {
                this.classList.remove('active');
            }
        });
    });
}

function initializeCopyButtons() {
    const copyButtons = document.querySelectorAll('.copy-button');

    copyButtons.forEach(button => {
        button.addEventListener('click', function() {
            const targetId = this.getAttribute('data-copy-target');
            const target = document.getElementById(targetId);

            if (target) {
                const textToCopy = target.textContent || target.value;

                navigator.clipboard.writeText(textToCopy).then(() => {
                    const originalText = this.textContent;
                    this.textContent = '✓ Másolva!';

                    setTimeout(() => {
                        this.textContent = originalText;
                    }, 2000);
                }).catch(err => {
                    console.error('Copy failed:', err);
                    showError('Másolás sikertelen');
                });
            }
        });
    });
}

async function checkPaymentStatus(paymentId) {
    try {
        const response = await fetch(`/api/payment/status/${paymentId}`);
        const result = await response.json();

        if (result.success) {
            updatePaymentStatusUI(paymentId, result.status);

            if (result.status === 'completed') {
                showSuccess('Fizetés sikeresen teljesítve!');
            } else if (result.status === 'failed') {
                showError('Fizetés sikertelen');
            }
        }

        return result;
    } catch (error) {
        console.error('Status check error:', error);
        return null;
    }
}

function updatePaymentStatusUI(paymentId, status) {
    const statusElements = document.querySelectorAll(`[data-payment-id="${paymentId}"] .payment-status`);

    statusElements.forEach(element => {
        element.textContent = getStatusText(status);
        element.className = 'badge badge-' + getStatusClass(status);
    });

    const statusDots = document.querySelectorAll(`[data-payment-id="${paymentId}"] .status-dot`);
    statusDots.forEach(dot => {
        dot.className = 'status-dot ' + status;
    });
}

function getStatusText(status) {
    const statusMap = {
        'pending': 'Folyamatban',
        'processing': 'Feldolgozás alatt',
        'completed': 'Teljesítve',
        'failed': 'Sikertelen',
        'cancelled': 'Megszakítva'
    };
    return statusMap[status] || status;
}

function getStatusClass(status) {
    const classMap = {
        'pending': 'warning',
        'processing': 'info',
        'completed': 'success',
        'failed': 'error',
        'cancelled': 'error'
    };
    return classMap[status] || 'info';
}

function showSuccess(message) {
    showAlert(message, 'success');
}

function showError(message) {
    showAlert(message, 'error');
}

function showAlert(message, type) {
    const alertContainer = document.getElementById('alert-container') || createAlertContainer();

    const alert = document.createElement('div');
    alert.className = `alert alert-${type}`;
    alert.textContent = message;

    alertContainer.appendChild(alert);

    setTimeout(() => {
        alert.style.opacity = '0';
        setTimeout(() => {
            alert.remove();
        }, 300);
    }, 5000);
}

function createAlertContainer() {
    const container = document.createElement('div');
    container.id = 'alert-container';
    container.style.position = 'fixed';
    container.style.top = '20px';
    container.style.right = '20px';
    container.style.zIndex = '9999';
    container.style.maxWidth = '400px';
    document.body.appendChild(container);
    return container;
}

function formatCurrency(amount, currency = 'HUF') {
    return new Intl.NumberFormat('hu-HU', {
        style: 'currency',
        currency: currency
    }).format(amount);
}

function formatDate(dateString) {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('hu-HU', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    }).format(date);
}

window.checkPaymentStatus = checkPaymentStatus;
window.formatCurrency = formatCurrency;
